<script>
function confirmReceivablePaymentVoid(form) {
    const reason = form.querySelector('[name="reason"]').value.trim();
    if (reason.length < 10) {
        alert('Tuliskan alasan pembatalan minimal 10 karakter.');
        return false;
    }

    const approved = confirm(
        'PERHATIAN: Anda akan membatalkan bukti pelunasan {{ $barh->NOBAYAR }}.\n\n' +
        'Dampak pembatalan:\n' +
        '• Status pelunasan berubah menjadi DIBATALKAN.\n' +
        '• Sistem membuat jurnal pembalik.\n' +
        '• Saldo invoice terkait akan terbuka kembali.\n' +
        '• Transaksi yang sudah dibatalkan tidak dapat diedit.\n\n' +
        'Pastikan nomor bukti, invoice, dan alasan pembatalan sudah benar.'
    );
    if (!approved) return false;

    const confirmation = prompt('Ketik BATAL untuk mengonfirmasi pembatalan bukti {{ $barh->NOBAYAR }}:');
    if (confirmation !== 'BATAL') {
        alert('Pembatalan tidak diproses karena konfirmasi tidak sesuai.');
        return false;
    }

    return true;
}
</script>
